#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000005;
const int MOD_CONST = 1000000007;

int arr[MAXN];
bool visited_flag[MAXN];
int p_input, k_input;

int main()
{
    cin >> p_input >> k_input;
    if (k_input == 0) {
        long long total = 1;
        for (int i = 1; i < p_input; ++i) {
            total = (total * p_input) % MOD_CONST;
        }
        cout << total << "\n";
        return 0;
    }
    for (int i = 1; i < p_input; ++i) {
        arr[i] = (long long)k_input * i % p_input;
    }
    long long result = 1;
    for (int i = 0; i < p_input; ++i) {
        if (!visited_flag[i]) {
            int cycle_len = 0;
            int index = i;
            int product_tmp = 1;
            while (!visited_flag[index]) {
                visited_flag[index] = true;
                index = arr[index];
                cycle_len++;
                product_tmp = (long long)product_tmp * k_input % p_input;
            }
            if (cycle_len == 1) {
                int multiplier = (k_input == 1) ? p_input : 1;
                result = (result * multiplier) % MOD_CONST;
            } else {
                assert(product_tmp == 1);
                result = (result * p_input) % MOD_CONST;
            }
        }
    }
    cout << result << "\n";
}
